package de.powerradio.studio;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.concurrent.*;
public class StudioWidget extends AppWidgetProvider {
static String[] stations={"powerradio","powerradio-pop"};
static int[] listeners={R.id.listeners0,R.id.listeners1}, songs={R.id.song0,R.id.song1}, shows={R.id.show0,R.id.show1}, next={R.id.next0,R.id.next1}, counts={R.id.count0,R.id.count1}, plays={R.id.play0,R.id.play1};
static Object get(String s,String path)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://api.laut.fm/station/"+s+path).openConnection();c.setConnectTimeout(2500);c.setReadTimeout(2500);c.setUseCaches(false);try(InputStream in=c.getInputStream()){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);return new JSONTokener(b.toString("UTF-8")).nextValue();}finally{c.disconnect();}}
static class Data {int l=-1;String song="Titel nicht verfügbar",show="Sendeplan nicht verfügbar",next="Keine Daten";long time=0;boolean online=false;}
static void plan(Data d,Object raw){JSONArray a=raw instanceof JSONArray?(JSONArray)raw:raw instanceof JSONObject?((JSONObject)raw).optJSONArray("schedule"):null;if(a==null&&raw instanceof JSONObject)a=((JSONObject)raw).optJSONArray("items");if(a==null)return;ZoneId z=ZoneId.of("Europe/Berlin");ZonedDateTime now=ZonedDateTime.now(z);long current=Long.MIN_VALUE,future=Long.MAX_VALUE;String[] days={"mon","tue","wed","thu","fri","sat","sun"};for(int k=0;k<a.length();k++){JSONObject x=a.optJSONObject(k);if(x==null)continue;String day=x.optString("day").toLowerCase(Locale.ROOT);int h=x.optInt("hour",-1);if(h<0||h>23)continue;for(int offset=-7;offset<=7;offset++){LocalDate date=now.toLocalDate().plusDays(offset);if(!day.startsWith(days[date.getDayOfWeek().getValue()-1]))continue;long t=date.atTime(h,0).atZone(z).toInstant().toEpochMilli();String name=x.optString("name","Unbenannte Sendung");if(t<=System.currentTimeMillis()&&t>current){current=t;d.show=name;}if(t>System.currentTimeMillis()&&t<future){future=t;d.time=t;d.next=name+" · "+DateTimeFormatter.ofPattern("EEE HH:mm",Locale.GERMAN).format(Instant.ofEpochMilli(t).atZone(z));}}}}
@Override public void onReceive(Context c,Intent intent){if("de.powerradio.REFRESH".equals(intent.getAction())){AppWidgetManager m=AppWidgetManager.getInstance(c);onUpdate(c,m,m.getAppWidgetIds(new ComponentName(c,StudioWidget.class)));}else super.onReceive(c,intent);}
@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){PendingResult pending=goAsync();new Thread(()->{ExecutorService pool=Executors.newFixedThreadPool(6);try{Data[] d={new Data(),new Data()};ArrayList<Callable<Void>> jobs=new ArrayList<>();for(int i=0;i<2;i++){final int k=i; jobs.add(()->{try{Object x=get(stations[k],"/listeners");d[k].l=x instanceof JSONObject?((JSONObject)x).optInt("listeners",((JSONObject)x).optInt("current",((JSONObject)x).optInt("count",-1))):Integer.parseInt(x.toString());}catch(Exception ignored){}return null;});jobs.add(()->{try{JSONObject j=(JSONObject)get(stations[k],"/current_song");JSONObject artist=j.optJSONObject("artist");d[k].song=(artist==null?j.optString("artist",""):artist.optString("name"))+" – "+j.optString("title",j.optString("name","—"));d[k].online=true;}catch(Exception ignored){}return null;});jobs.add(()->{try{plan(d[k],get(stations[k],"/schedule"));}catch(Exception ignored){}return null;});}pool.invokeAll(jobs,6,TimeUnit.SECONDS);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);Intent refresh=new Intent(c,StudioWidget.class).setAction("de.powerradio.REFRESH");v.setOnClickPendingIntent(R.id.header,PendingIntent.getBroadcast(c,90,refresh,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));for(int i=0;i<2;i++){Intent a=new Intent(c,RadioService.class).putExtra("station",i);v.setOnClickPendingIntent(plays[i],PendingIntent.getForegroundService(c,i,a,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));v.setTextViewText(plays[i],RadioService.active==i?"■ STOP":"▶ PLAY");v.setTextViewText(listeners[i],(d[i].online?"● ON AIR":"Status unbekannt")+" · Hörer: "+(d[i].l<0?"—":d[i].l));v.setTextViewText(songs[i],d[i].song);v.setTextViewText(shows[i],"Jetzt: "+d[i].show);v.setTextViewText(next[i],"Danach: "+d[i].next);v.setViewVisibility(counts[i],android.view.View.VISIBLE);v.setChronometerCountDown(counts[i],true);v.setChronometer(counts[i],SystemClock.elapsedRealtime()+Math.max(0,d[i].time-System.currentTimeMillis()),d[i].time>0?"Wechsel in %s":"Countdown nicht verfügbar",d[i].time>0);}v.setTextViewText(R.id.header,"POWER RADIO • "+(d[0].l>=0&&d[1].l>=0?(d[0].l+d[1].l)+" Hörer":"STUDIO")+"    ↻");m.updateAppWidget(ids,v);}catch(Exception ignored){}finally{pool.shutdownNow();pending.finish();}}).start();}
}